<template>
    <v-card>
        <v-card-text>
            <StrLoading v-if="is_fetching" :data="is_fetching" label="Connecting to Catalog Server..."/>
            <v-row v-else>
                <v-col cols="12" lg="6" md="6" sm="12">
                    <StrCheckbox
                        v-for="brand in manufacturers.slice(0, 12)"
                        :key="brand.id"
                        :label="brand.name"
                        style="margin-top: 5px"
                        :is_checked="IsChecked(brand.id)"
                        @onChange="(v)=>ToggleCheck(v,brand.id)">
                    </StrCheckbox>
                </v-col>
                <v-col cols="12" lg="6" md="6" sm="12">
                    <StrCheckbox
                        v-for="brand in manufacturers.slice(12, 24)"
                        :key="brand.id"
                        :label="brand.name"
                        style="margin-top: 5px"
                        :is_checked="IsChecked(brand.id)"
                        @onChange="(v)=>ToggleCheck(v,brand.id)">
                    </StrCheckbox>
                </v-col>
            </v-row>
        </v-card-text>
    </v-card>
</template>

<script>
import {mapState} from "vuex";
import StrCheckbox from "@/components/StrCheckbox.vue";
import RowTitle from "@/components/RowTitle.vue";
import StrLoading from "@/components/StrLoading.vue";

export default {
    components: {StrLoading, RowTitle, StrCheckbox},
    computed: {
        ...mapState(['settings','manufacturers','is_fetching']),
    },
    methods: {
        ToggleCheck(is_checked,brand_id) {
            console.log("is_checked: ", is_checked);
            if (is_checked) {
                if (!this.settings.manufacturers_allowed.includes(+brand_id)) {
                    this.settings.manufacturers_allowed.push(+brand_id);
                }
            }
            else {
                const index = this.settings.manufacturers_allowed.indexOf(+brand_id);
                if (index != -1) {
                    this.settings.manufacturers_allowed.splice(index,1);
                }
            }
        },
        IsChecked(brand_id) {
            return this.settings.manufacturers_allowed.includes(brand_id);
        },
    }
}
</script>
