import AnalyticsReportsTable from "@/components/analytics/AnalyticsReportsTable.vue";
import AnalyticsRealtimeTable from "@/components/analytics/AnalyticsRealtimeTable.vue";
export default {
    components: {
        AnalyticsSettings,
        StrTextField,
        AnalyticsWindowTitle,
        AnalyticsReportsTable,
        AnalyticsRealtimeTable,
    },
    mixins: [AnalyticsMixins],
    computed: {
        ...mapState(['analytics']),
    },
}
</script>
