<template>
    <v-row>
        <v-col cols="12" lg="8" md="8" sm="12" offset-lg="2" offset-md="2">
            <v-container>

                <v-stepper class="setup-wizard" v-model="wizard_step" hide-actions alt-labels>
                    <v-stepper-header>
                        <v-stepper-item
                            v-for="(item, index) in wizard_items"
                            :class="{'step-done':wizard_step>index+1}"
                            :key="index+1"
                            :title="item"
                            :step="index+1"
                            :value="index+1">
                            <template #icon>
                                <v-icon v-if="wizard_step > (index+1)" color="green" opacity="1">mdi-check-circle-outline</v-icon>
                                <v-icon v-else-if="wizard_step === (index+1)" color="blue" opacity="1">mdi-circle-slice-8</v-icon>
                                <v-icon v-else color="grey" opacity="1">mdi-checkbox-blank-circle-outline</v-icon>
                            </template>
                            <template #title>
                                {{ item }}
                                <div v-if="(index+1)<5" class="stepper-line" :class="{'step-done':wizard_step>index+1}"></div>
                            </template>
                        </v-stepper-item>
                    </v-stepper-header>

                    <v-stepper-window>
                        <v-stepper-window-item :value="1">
                            <Disclaimer/>
                            <Flexed justify="center">
                                <v-btn append-icon="mdi-chevron-double-right" :loading="is_loading" color="primary" @click="Next">Agree and Continue</v-btn>
                            </Flexed>
                        </v-stepper-window-item>
                        <v-stepper-window-item :value="2">
                            <SqueezeToMiddle columns="10" offset="1">
                                <RowTitle top="5px" bottom="20px">CRM Webhook & Catalog API</RowTitle>
                                <RowTitle bottom="50px" size="small">The Catalog API Key and CRM Automation URL are provided by 1-800 Office Solutions to enable catalog access and automate lead delivery to your CRM. If you haven’t received these yet, you may ask your representative before continuing the setup.</RowTitle>
                                <CatalogApiKey/>
                                <div class="mt-5 mb-5"></div>
                                <CrmWebhookUrl/>
                                <StrLoading :data="is_fetching" label="Connecting to Catalog Server..."/>
                            </SqueezeToMiddle>
                            <Flexed justify="space-between">
                                <v-btn prepend-icon="mdi-chevron-double-left" :disabled="is_fetching" variant="tonal" color="default" @click="Prev">Previous</v-btn>
                                <v-btn append-icon="mdi-chevron-double-right" color="primary" :disabled="!settings.catalog_api_key || is_fetching" @click="FetchProductsAndSave">Save and Continue</v-btn>
                            </Flexed>
                        </v-stepper-window-item>
                        <v-stepper-window-item :value="3">
                            <RowTitle top="5px">Product Settings and Filters</RowTitle>
                            <SqueezeToMiddle columns="8" offset="2">
                                <div class="text-center">
                                    <RowTitle size="small" :strong="true" top="50px">Enable/Disable Brand Display</RowTitle>
                                    <p class="input-description">Use the checkboxes below to display or hide specific brands in the Catalog.</p>
                                </div>
                                <ManufacturersList/>
                            </SqueezeToMiddle>
                            <SqueezeToMiddle columns="8" offset="2">
                                <RowTitle :strong="true" bottom="20px" size="small">Other Settings (Optional)</RowTitle>
                                <CatalogFeaturesInputs/>
                            </SqueezeToMiddle>
                            <Flexed justify="space-between">
                                <v-btn prepend-icon="mdi-chevron-double-left" :disabled="is_loading" variant="tonal" color="default" @click="Prev">Previous</v-btn>
                                <v-btn append-icon="mdi-chevron-double-right" :loading="is_loading" color="primary" :disabled="!settings.catalog_api_key" @click="Next">Save and Continue</v-btn>
                            </Flexed>
                        </v-stepper-window-item>
                        <v-stepper-window-item :value="4">
                            <RowTitle top="5px" bottom="10px">Personalize your Catalog</RowTitle>
                            <RowTitle size="small" bottom="50px">Adjust the look and feel of your Catalog to match your brand and preferences.</RowTitle>
                            <SqueezeToMiddle columns="8" offset="2">
                                <!--TOPBAR-->
                                <RowTitle size="small" bottom="10px" :strong="true">Navigation Bar</RowTitle>
                                <DemoTopbar/>
                                <StrColorPicker label="Navbar Color" v-model="settings.colors.topbar"/>

                                <v-divider style="margin:25px"/>

                                <!--MODALS-->
                                <RowTitle size="small" bottom="10px" :strong="true">Forms and Modals</RowTitle>
                                <StrColorPicker label="Forms Modals" v-model="settings.colors.modals" class="mb-3"/>
                                <DemoModal/>

                                <v-divider style="margin:25px"/>

                                <!--BUTTONS AND ELEMENTS-->
                                <RowTitle size="small" bottom="10px" :strong="true">Buttons and other Elements</RowTitle>
                                <StrColorPicker label="Forms Modals" v-model="settings.colors.buttons" class="mb-3"/>
                                <DemoButtons/>
                            </SqueezeToMiddle>
                            <Flexed justify="space-between">
                                <v-btn prepend-icon="mdi-chevron-double-left" :disabled="is_loading" variant="tonal" color="default" @click="Prev">Previous</v-btn>
                                <v-btn append-icon="mdi-chevron-double-right" :loading="is_loading" color="primary" @click="Next">Save and Continue</v-btn>
                            </Flexed>
                        </v-stepper-window-item>
                        <v-stepper-window-item :value="5">
                            <SqueezeToMiddle columns="8" offset="2">
                                <AnalyticsOauth v-if="!HasAccessToken && !PropertySelected"/>
                                <AnalyticsPropertyPicker v-else-if="HasAccessToken && !PropertySelected"/>
                                <div class="text-center" v-else>
                                    <h1><v-icon>mdi-google-analytics</v-icon> Your Catalog is now connected to Analytics!</h1>
                                    <p>If you ever need to reconnect or change your Google Analytics setup, you’ll be able to do that later with ease.</p>
                                </div>
                            </SqueezeToMiddle>
                            <Flexed justify="space-between">
                                <v-btn prepend-icon="mdi-chevron-double-left" :disabled="is_loading" variant="tonal" color="default" @click="Prev">Previous</v-btn>
                                <div>
                                    <v-btn variant="text" color="default" @click="FinishSetup" class="mr-3">I'll do this later</v-btn>
                                    <v-btn append-icon="mdi-check" :disabled="!Property" :loading="is_loading" color="primary" @click="FinishSetup">Finish Setup</v-btn>
                                </div>
                            </Flexed>
                        </v-stepper-window-item>

                        <!--Thank You Message-->
                        <div v-if="wizard_step==6">
                            <Flexed justify="center">
                                <v-icon size="70px" color="green">mdi-check-circle</v-icon>
                            </Flexed>
                            <RowTitle top="5px" bottom="20px">We're done setting up your Catalog!</RowTitle>
                            <RowTitle size="small" style="width:400px;margin:auto">You many use the shortcode <b>[one-800-products-app]</b> on any page to display the Catalog.</RowTitle>
                            <div class="text-center mt-5 mb-5">
                                <v-btn class="mb-5" variant="tonal" size="large" append-icon="mdi-play-circle-outline" color="success" @click="ReloadPage">Continue</v-btn>
                            </div>
                        </div>
                    </v-stepper-window>
                </v-stepper>
            </v-container>
        </v-col>
    </v-row>
</template>

<script>
import {mapState, mapActions} from 'vuex';
import AllMixins from "@/mixins/AllMixins";
import Flexed from "@/components/Flexed.vue";
import RowTitle from "@/components/RowTitle.vue";
import DemoModal from "@/components/DemoModal.vue";
import DemoTopbar from "@/components/DemoTopbar.vue";
import OS1800Logo from "@/components/OS1800Logo.vue";
import DemoButtons from "@/components/DemoButtons.vue";
import StrCheckbox from "@/components/StrCheckbox.vue";
import StrTextField from "@/components/StrTextField.vue";
import StrColorPicker from "@/components/StrColorPicker.vue";
import Disclaimer from "@/components/features/Disclaimer.vue";
import ItemsPerPage from "@/components/features/ItemsPerPage.vue";
import CatalogApiKey from "@/components/features/CatalogApiKey.vue";
import CrmWebhookUrl from "@/components/features/CrmWebhookUrl.vue";
import ProductPricing from "@/components/features/ProductPricing.vue";
import CatalogPageTitle from "@/components/features/CatalogPageTitle.vue";
import ManufacturersList from "@/components/features/ManufacturersList.vue";
import ProductExclusions from "@/components/features/ProductExclusions.vue";
import SqueezeToMiddle from "@/components/SqueezeToMiddle.vue";
import StrLoading from "@/components/StrLoading.vue";
import DisplayFeatured from "@/components/features/DisplayFeatured.vue";
import AnalyticsOauth from "@/components/analytics/AnalyticsOauth.vue";
import AnalyticsMixins from "@/mixins/AnalyticsMixins.js";
import AnalyticsPropertyPicker from "@/components/analytics/AnalyticsPropertyPicker.vue";
import DisplayShopBanner from "@/components/features/DisplayShopBanner.vue";
import CatalogFeaturesInputs from "@/components/features/CatalogFeaturesInputs.vue";

export default {
    data: () => ({
        wizard_step: 1,
        wizard_items: [
            'Introduction',
            'Connections',
            'Product Settings',
            'Customization',
            'Analytics',
        ],
    }),
    mixins: [AllMixins,AnalyticsMixins],
    components: {
        CatalogFeaturesInputs,
        DisplayShopBanner,
        AnalyticsPropertyPicker,
        AnalyticsOauth,
        DisplayFeatured,
        StrLoading,
        SqueezeToMiddle,
        DemoButtons,
        DemoTopbar,
        DemoModal,
        OS1800Logo,
        RowTitle,
        StrColorPicker,
        ProductExclusions,
        ItemsPerPage,
        ProductPricing,
        StrTextField,
        StrCheckbox,
        Flexed,
        Disclaimer,
        CrmWebhookUrl,
        CatalogApiKey,
        ManufacturersList,
        CatalogPageTitle
    },
    computed: {
        ...mapState([
            'products',
            'settings',
            'is_loading',
            'is_syncing',
            'is_fetching',
            'manufacturers'
        ]),
    },
    methods: {
        ...mapActions([
            'SetAnyState',
            'SetSuccess',
            'SetError',
        ]),
        Next() {
            this.SaveSettings().then(() => {
                this.wizard_step++;
            });
        },
        Prev() {
            this.wizard_step--;
        },
        FinishSetup() {
            this.SaveSettings(false,true,false).then(()=>{
                this.wizard_step++;
                this.SetSuccess("Thank you for completing the setup!");
            });
        },
        ReloadPage() {
            location.href = "/wp-admin/admin.php?page=1-800-products";
        },
        FetchProductsAndSave() {
            this.FetchProducts().then(() => {
                this.Next();
            });
        }
    },
    mounted() {
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('tab')) {
            this.wizard_step = parseInt(urlParams.get('tab'))-1;
        }
    }
};
</script>
<style lang="scss">
.setup-wizard {
    .v-stepper-item {
        opacity: 1;
        .step-done {
            color: #1867c0;
        }
    }
    .v-avatar {
        background: none !important;
        font-size: 20px !important;
        padding: 0 !important;
        .v-icon {
            font-size: 30px !important;
            z-index: 99999 !important;
            position: absolute !important;
            background: white !important;
        }
    }
    .stepper-line {
        background: #bebebe;
        position: absolute;
        height: 4px;
        top: 35px;
        margin-left: 50px;
        z-index: -1;
        &.step-done {
            background: #7dbc67;
            background: #07b5fa;
            background: linear-gradient(270deg,rgba(7, 181, 250, 1) 0%, rgba(87, 199, 133, 1) 50%, rgba(201, 255, 92, 1) 100%);
        }
        @media(max-width: 2160px) {
            & {
                width: 145%;
            }
        }
        @media(max-width: 1920px) {
            & {
                width: 130%;
            }
        }
        @media(max-width: 1800px) {
            & {
                width: 115%;
            }
        }
        @media(max-width: 1600px) {
            & {
                width: 100%;
            }
        }
    }
}
</style>
