<template>
    <AnalyticsWindowTitle title="Catalog Real-time Traffic" subtitle="This real-time data only tracks visits specifically to the <a href='/products'>products</a> page."/>
    <v-data-table :loading="analytics.is_loading" density="comfortable" :headers="headers" :items="analytics.realtime_users">
        <template #item.platform="{ item }">
            <span class="text-capitalize"><v-icon class="mb-1" size="small">mdi-web</v-icon> Web</span>
        </template>
        <template #item.country="{ item }">
            <span class="font-weight-bold">{{ item.country }}</span>
        </template>
        <template #item.minutesAgo="{ item }">
            <span>{{ item.minutesAgo == 0 ? 'Just now' : item.minutesAgo + ' mins ago' }}</span>
        </template>
        <template #item.deviceCategory="{ item }">
            <v-btn size="x-small" style="font-size:16px" variant="tonal" color="primary" elevation="0" v-if="item.deviceCategory=='desktop'" icon="mdi-cellphone-wireless"/>
            <v-btn size="x-small" style="font-size:16px" variant="tonal" color="primary" elevation="0" v-else icon="mdi-desktop-tower-monitor"/>
        </template>
    </v-data-table>
    <AnalyticsLoader/>
</template>

<script>
import {mapState} from "vuex";
import AnalyticsWindowTitle from "@/components/analytics/AnalyticsWindowTitle.vue";
import AnalyticsLoader from "@/components/analytics/AnalyticsLoader.vue";
import AnalyticsMixins from "@/mixins/AnalyticsMixins.js";

export default {
    data: () => ({
        headers: [
            { sortable: true, title: 'Platform', key: 'platform' },
            { sortable: true, title: 'Country', key: 'country' },
            { sortable: true, title: 'Last Seen', key: 'minutesAgo' },
            { sortable: true, title: 'Device', key: 'deviceCategory' }
        ],
    }),
    mixins: [AnalyticsMixins],
    components: {AnalyticsLoader, AnalyticsWindowTitle},
    computed: {
        ...mapState(['analytics'])
    },
    mounted() {
        if (this.HasAccessToken && this.PropertySelected) {
            this.FetchRealtimeUsers();
        }
    }
}
</script>
