<template>
    <v-select
        variant="outlined"
        :return-object="true"
        density="comfortable"
        id="property-selector"
        item-title="display_name"
        :disabled="PropertySelected"
        :items="analytics.properties"
        :loading="analytics.is_loading"
        v-model="analytics.property_model"
        label="Select your Analytics Property">
    </v-select>

    <div class="d-flex justify-space-between">
        <v-btn
            color="red"
            variant="tonal"
            text="Disconnect"
            :disabled="!Property"
            append-icon="mdi-close"
            @click="DisconnectGoogle">
        </v-btn>
        <v-btn
            color="primary"
            text="Use this Property"
            @click="SetPropertyAndSave"
            prepend-icon="mdi-google-analytics"
            :disabled="!analytics.property_model || PropertySelected">
        </v-btn>
    </div>
</template>

<script>
import {mapState} from "vuex";
import AnalyticsMixins from "@/mixins/AnalyticsMixins.js";
import Flexed from "@/components/Flexed.vue";

export default {
    components: {Flexed},
    mixins: [AnalyticsMixins],
    computed: {
        ...mapState(['analytics','google_config'])
    },
    mounted() {
        if (this.HasAccessToken) {
            this.FetchAnalyticsProperties();
        }
        if (this.Property) {
            this.SetGaSettingState('property_model', {...this.Property})
        }
    }
}
</script>
