<template>
    <div v-if="google_config">
        <div v-if="HasAccessToken">
            <AnalyticsHeading v-if="!PropertySelected"/>

            <!--If access granted, property selected-->
            <AnalyticsLayout v-if="PropertySelected"/>

            <!--If Access token received, but need select Property-->
            <SqueezeToMiddle v-else columns="8" offset="2">
                <AnalyticsPropertyPicker/>
            </SqueezeToMiddle>
        </div>

        <!--If no Google Access yet, begin Oauth-->
        <SqueezeToMiddle v-else columns="8" offset="2">
            <AnalyticsOauth/>
        </SqueezeToMiddle>
    </div>
</template>

<script>
import {mapActions, mapState} from "vuex";
import AllMixins from "@/mixins/AllMixins.js";
import AnalyticsMixins from "@/mixins/AnalyticsMixins.js";
import SqueezeToMiddle from "@/components/SqueezeToMiddle.vue";
import AnalyticsLayout from "@/components/analytics/AnalyticsLayout.vue";
import AnalyticsHeading from "@/components/analytics/AnalyticsHeading.vue";
import AnalyticsPropertyPicker from "@/components/analytics/AnalyticsPropertyPicker.vue";
import AnalyticsOauth from "@/components/analytics/AnalyticsOauth.vue";
export default {
    components: {
        AnalyticsOauth,
        AnalyticsPropertyPicker,
        AnalyticsHeading,
        SqueezeToMiddle,
        AnalyticsLayout
    },
    mixins: [
        AllMixins,
        AnalyticsMixins
    ],
}
</script>
<style>
#property-selector,
#property-selector:focus,
#property-selector:active,
#property-selector:hover {
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
}
</style>
