<template>
    <AnalyticsWindowTitle title="Catalog Report" subtitle="Displays lifetime analytics data specifically for the <a href='/products'>products</a> page."/>

    <!--Dropdown-->
    <v-select :loading="analytics.is_loading" @update:model-value="OnDateRangeChange" label="Select a date" density="compact" v-model="predefined_model" id="timestamp-selector" variant="outlined" :items="predefined_dates"/>

    <!--Custom date select-->
    <v-row v-if="predefined_model=='custom-date'">
        <v-col cols="12" lg="5" md="5" sm="12">
            <StrTextField readonly :model-value="HumanReadableDate(analytics.from_date)" label="Choose a start date" @click="ToggleDatepicker(1)"/>
            <v-date-picker :max="new Date().toISOString().split('T')[0]" @update:model-value="SetDatepickerDate($event,'from_date')" hide-header v-if="analytics.show_datepicker==1" class="border mt-1"/>
        </v-col>
        <v-col cols="12" lg="5" md="5" sm="12">
            <StrTextField readonly :model-value="HumanReadableDate(analytics.end_date)" label="Choose a end date" @click="ToggleDatepicker(2)"/>
            <v-date-picker :max="new Date().toISOString().split('T')[0]" @update:model-value="SetDatepickerDate($event,'end_date')" hide-header v-if="analytics.show_datepicker==2" class="border mt-1"/>
        </v-col>
        <v-col cols="12" lg="2" md="2">
            <v-btn @click="FetchHistoryReport" class="mt-lg-5 mt-0 d-flex ml-auto" color="primary">Submit</v-btn>
        </v-col>
    </v-row>

    <!--Graph/chart here-->
    <v-card class="border">
        <v-chart :option="chart_options" autoresize style="height: 300px"/>
    </v-card>

    <!--Loader circle-->
    <AnalyticsLoader/>
</template>

<script>
import moment from "moment";
import {mapState} from "vuex";
import Flexed from "@/components/Flexed.vue";
import StrTextField from "@/components/StrTextField.vue";
import AnalyticsMixins from "@/mixins/AnalyticsMixins.js";
import AnalyticsLoader from "@/components/analytics/AnalyticsLoader.vue";
import AnalyticsWindowTitle from "@/components/analytics/AnalyticsWindowTitle.vue";

/* Chart */
import VChart from 'vue-echarts'
import * as echarts from 'echarts/core'
import { LineChart } from 'echarts/charts'
import { CanvasRenderer } from 'echarts/renderers'
import {
    TitleComponent,
    TooltipComponent,
    GridComponent,
    LegendComponent
} from 'echarts/components';

echarts.use([
    LineChart,
    TitleComponent,
    TooltipComponent,
    GridComponent,
    LegendComponent,
    CanvasRenderer
]);


export default {
    components: {
        VChart,
        Flexed,
        StrTextField,
        AnalyticsLoader,
        AnalyticsWindowTitle
    },
    mixins: [
        AnalyticsMixins
    ],
    data:() => ({
        predefined_dates: [
            {value: 'last-7-days',  title: 'Last 7 days'},
            {value: 'last-30-days', title: 'Last 30 days'},
            {value: 'last-90-days', title: 'Last 3 Months'},
            {value: 'custom-date',  title: 'Select date...'},
        ],
        predefined_model: 'last-7-days',
        chart_options: {}
    }),
    computed :{
        ...mapState(['analytics']),
    },
    methods: {
        ToggleDatepicker(n) {
            if (this.analytics.show_datepicker == n) {
                this.SetGaSettingState('show_datepicker', null);
            } else {
                this.SetGaSettingState('show_datepicker', n);
            }
        },
        OnDateRangeChange(selection) {
            const analyticsCopy = {...this.analytics}
            if (selection == 'last-7-days') {
                analyticsCopy.from_date = moment().subtract(7, 'days').format('YYYY-MM-DD');
                analyticsCopy.end_date = moment().format('YYYY-MM-DD');
            }
            else if (selection == 'last-30-days') {
                analyticsCopy.from_date = moment().subtract(30, 'days').format('YYYY-MM-DD');
                analyticsCopy.end_date = moment().format('YYYY-MM-DD');
            }
            else if (selection == 'last-90-days') {
                analyticsCopy.from_date = moment().subtract(90, 'days').format('YYYY-MM-DD');
                analyticsCopy.end_date = moment().format('YYYY-MM-DD');
            }
            else {
                analyticsCopy.from_date = null;
                analyticsCopy.end_date = null;
            }
            this.SetAnyState({
                target: 'analytics',
                value: analyticsCopy,
            });
            if (selection != "custom-date") {
                this.FetchHistoryReport();
            }
        },
        SetDatepickerDate(the_date,target_date) {
            const new_date = moment(the_date).format('YYYY-MM-DD');
            this.SetGaSettingState(target_date, new_date);
        }
    },
    mounted() {
        this.OnDateRangeChange('last-7-days');
        this.FetchHistoryReport();
    },
    watch: {
        "analytics.history_report": {
            immediate: true,
            handler(data) {
                this.chart_options = {
                    tooltip: {
                        trigger: 'axis'
                    },
                    xAxis: {
                        type: 'category',
                        data: data.map(item => item.date)
                    },
                    yAxis: {
                        type: 'value'
                    },
                    series: [
                        {
                            name: 'Page Views',
                            type: 'line',
                            data: data.map(item => item.views),
                            smooth: true,
                            lineStyle: {
                                color: '#1976D2'
                            },
                            itemStyle: {
                                color: '#1976D2'
                            }
                        }
                    ]
                }
            }
        }
    }
}
</script>
