<template>
    <v-row>
        <v-col cols="12" lg="10" md="10" sm="12" offset-lg="1" offset-md="1">
            <v-container style="max-width: 991px;">
                <v-card rounded="lg">
                    <v-tabs v-model="active_tab" class="mb-4 border-b">
                        <v-spacer/>
                        <v-tab value="1" prepend-icon="mdi-cogs">Products</v-tab>
                        <v-tab value="2" prepend-icon="mdi-star">Styling</v-tab>
                        <v-tab value="3" prepend-icon="mdi-webhook">API</v-tab>
                        <v-tab value="4" prepend-icon="mdi-robot">AI Assistant</v-tab>
                        <v-tab value="5" prepend-icon="mdi-wrench-clock">Automations</v-tab>
                        <v-tab value="6" prepend-icon="mdi-google-analytics">Analytics</v-tab>
                        <v-spacer/>
                    </v-tabs>
                    <v-window v-model="active_tab" class="pb-5">
                        <v-window-item value="1">
                            <SqueezeToMiddle columns="8" offset="2">
                                <RowTitle bottom="50px">Product Settings</RowTitle>
                                <RowTitle size="small" :strong="true">Enable/Disable Brand Display</RowTitle>
                                <ManufacturersList/>

                                <RowTitle :strong="true" top="20px" bottom="20px" size="small">Other Settings (Optional)</RowTitle>
                                <CatalogFeaturesInputs/>
                            </SqueezeToMiddle>
                        </v-window-item>
                        <v-window-item value="2">
                            <SqueezeToMiddle columns="8" offset="2">
                                <RowTitle bottom="50px">Customize the Look and Feel</RowTitle>
                                <RowTitle top="20px" size="small" bottom="10px" :strong="true">Navigation Bar</RowTitle>
                                <DemoTopbar/>
                                <StrColorPicker v-model="settings.colors.topbar"/>

                                <v-divider style="margin:25px"/>

                                <!--MODALS-->
                                <RowTitle size="small" bottom="10px" :strong="true">Forms and Modals</RowTitle>
                                <StrColorPicker v-model="settings.colors.modals" class="mb-3"/>
                                <DemoModal/>

                                <v-divider style="margin:25px"/>

                                <!--BUTTONS AND ELEMENTS-->
                                <RowTitle size="small" bottom="10px" :strong="true">Buttons and other Elements</RowTitle>
                                <StrColorPicker v-model="settings.colors.buttons" class="mb-3"/>
                                <DemoButtons/>
                            </SqueezeToMiddle>
                        </v-window-item>
                        <v-window-item value="3">
                            <SqueezeToMiddle columns="8" offset="2">
                                <RowTitle bottom="10px">Webhook and API</RowTitle>
                                <RowTitle bottom="30px" size="small" class="ml-auto mr-auto" style="width:500px">
                                    When updating your CRM integration, make sure all CRM fields are properly mapped to your Catalog data for smooth syncing.
                                </RowTitle>
                                <CatalogApiKey/>
                                <div class="mt-5 mb-5"></div>
                                <CrmWebhookUrl/>
                            </SqueezeToMiddle>
                        </v-window-item>
                        <v-window-item value="4">
                            <SqueezeToMiddle columns="8" offset="2">
                                <RowTitle bottom="20px">AI Assistant (Experimental)</RowTitle>
                                <AiAssistantAPI/>
                            </SqueezeToMiddle>
                        </v-window-item>
                        <v-window-item value="5">
                            <SqueezeToMiddle columns="8" offset="2">
                                <RowTitle bottom="20px">Automations</RowTitle>
                                <v-card border elevation="0" class="mt-1 mb-1">
                                    <v-card-text>
                                        <v-row>
                                            <v-col cols="6">
                                                <span class="font-weight-bold d-block mb-2">Generate products pages</span>
                                                <span>This will create each catalog product as pages.</span>
                                                <small>Est. completion: 15 mins</small>
                                            </v-col>
                                            <v-col cols="6">
                                                <v-btn prepend-icon="mdi-cog" :loading="is_syncing" style="margin-left: auto;width:100%" @click="SyncPages(true)" color="primary" class="mb-2">Generate Pages</v-btn>
                                                <v-btn variant="text" :disabled="is_syncing" style="margin-left: auto;width:100%" @click="RetractPages" size="x-small" color="red" v-if="settings.catalog_pages">Delete all Catalog Pages</v-btn>
                                            </v-col>
                                        </v-row>
                                    </v-card-text>
                                </v-card>
                            </SqueezeToMiddle>
                        </v-window-item>
                        <v-window-item value="6">
                            <SqueezeToMiddle columns="12" offset="0">
                                <GoogleAnalytics/>
                            </SqueezeToMiddle>
                        </v-window-item>
                    </v-window>
                    <v-card-actions v-if="active_tab<5" class="border-t mt-5 bg-grey-lighten-3">
                        <v-btn :disabled="active_tab=='tab-5'" color="primary" :loading="is_loading" variant="tonal" @click="RerunWizard" prepend-icon="mdi-hammer-wrench">Rerun Setup</v-btn>
                        <v-spacer/>
                        <v-btn :disabled="active_tab=='tab-5'" color="primary" :loading="is_loading" variant="elevated" @click="SaveSettings" prepend-icon="mdi-floppy">Save Settings</v-btn>
                    </v-card-actions>
                </v-card>
            </v-container>
        </v-col>
    </v-row>
</template>

<script>
import {mapState, mapActions} from 'vuex';
import AllMixins from "@/mixins/AllMixins.js";
import RowTitle from "@/components/RowTitle.vue";
import StrTextField from "@/components/StrTextField.vue";
import SqueezeToMiddle from '@/components/SqueezeToMiddle.vue';
import ItemsPerPage from "@/components/features/ItemsPerPage.vue";
import CatalogApiKey from "@/components/features/CatalogApiKey.vue";
import CrmWebhookUrl from "@/components/features/CrmWebhookUrl.vue";
import AiAssistantAPI from "@/components/features/AiAssistantAPI.vue";
import ProductPricing from "@/components/features/ProductPricing.vue";
import GoogleAnalytics from "@/components/features/GoogleAnalytics.vue";
import CatalogPageTitle from "@/components/features/CatalogPageTitle.vue";
import ProductExclusions from "@/components/features/ProductExclusions.vue";
import ManufacturersList from "@/components/features/ManufacturersList.vue";
import DisplayFeatured from "@/components/features/DisplayFeatured.vue";
import CatalogFeaturesInputs from "@/components/features/CatalogFeaturesInputs.vue";

export default {
    data: () => ({
        active_tab: '1',
    }),
    mixins: [AllMixins],
    components: {
        CatalogFeaturesInputs,
        DisplayFeatured,
        ProductExclusions,
        ManufacturersList,
        CatalogPageTitle,
        GoogleAnalytics,
        SqueezeToMiddle,
        AiAssistantAPI,
        ProductPricing,
        CrmWebhookUrl,
        CatalogApiKey,
        StrTextField,
        ItemsPerPage,
        RowTitle,
    },
    computed: {
        ...mapState(['settings','is_loading','is_syncing']),
    },
    methods: {
        ...mapActions(['SetAnyState','SetError','SetSuccess']),
    },
    created() {
        this.FetchProducts();
    },
    mounted() {
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('tab')) this.active_tab = urlParams.get('tab').toString();
    },
};
</script>
