<template>
    <label class="d-block mb-1">Catalog API Key
        <v-icon v-if="!settings.setup_wizard" size="small" class="ml-2 mt-1" title="Click to hide/show key" @click="show_key=!show_key">
            {{show_key ? 'mdi-eye-off' : 'mdi-eye'}}
        </v-icon>
    </label>
    <StrTextField
        :show_button="true"
        v-model="settings.catalog_api_key"
        :type="show_key ? 'text' : 'password'"
        placeholder="Paste your Catalog's API key here...">
    </StrTextField>
    <br>
</template>

<script>
import {mapState} from "vuex";
import StrTextField from "@/components/StrTextField.vue";

export default {
    components: {StrTextField},
    data: () => ({
        show_key: false,
    }),
    props: ['show_toggler'],
    computed: {
        ...mapState(['settings'])
    },
    mounted() {
        if (this.settings.setup_wizard) {
            this.show_key = true;
        }
    }
}
</script>
