<template>
    <v-app id="layout-app" v-if="settings">
        <v-app-bar density="comfortable" :elevation="1" class="border-b">
            <v-app-bar-title>
                <span v-if="settings.setup_wizard"><v-icon class="mb-1">mdi-cog</v-icon> Setup Your Catalog</span>
                <span v-else>
                    <v-icon>mdi-cog</v-icon> Products Catalog
                </span>
            </v-app-bar-title>
            <v-spacer/>
            <o-s1800-logo/>
        </v-app-bar>
        <v-main class="pt-5 bg-grey-lighten-4">
            <v-card-text>
                <slot name="content"/>
            </v-card-text>
            <v-footer v-if="$slots.footer" elevation="1" class="border-t">
                <slot name="footer"/>
            </v-footer>
        </v-main>
    </v-app>
</template>

<script>
import { VApp } from "vuetify/components";
import {mapActions, mapState} from "vuex";
import OS1800Logo from "@/components/OS1800Logo.vue";
export default {
    components: {OS1800Logo, VApp},
    data: () => ({
        drawer: true,
    }),
    methods: {
        ...mapActions(['SetAnyState'])
    },
    mounted() {
        const isMobile = window.innerWidth <= 768;
        if (isMobile) {
            this.drawer = false;
            this.SetAnyState({target:'config_drawer',value:false});
            this.SetAnyState({target:'is_mobile',value:isMobile});
        }
    },
    computed: {
        ...mapState(['settings'])
    }
}
</script>
<style lang="scss">
#catalog-admin-app {
    .v-toolbar {
	    position: relative !important;
    }
}
</style>
