<template>
  <p class="ma-0">Select Best Seller Products</p>
  <StrTextField readonly @onClick="picker.modal=true" type="text"
                :model-value="`(${settings.best_sellers.length}) Products. Click to add`"/>

  <!-- Exclusions Modal -->
  <v-dialog v-model="picker.modal" max-width="800px" persistent>
    <v-card>
      <v-toolbar color="#fff">
        <v-toolbar-title>
          <v-icon class="mb-1" size="x-small">mdi-pencil-circle</v-icon>
          Best Sellers
        </v-toolbar-title>
        <v-spacer></v-spacer>
        <v-btn icon @click="picker.modal=false">
          <v-icon>mdi-close</v-icon>
        </v-btn>
      </v-toolbar>
      <v-card-text class="scrollable-text">
        <StrTextField style="width:200px" v-model="picker.search" placeholder="Search here..."/>
        <br>
        <v-card elevation="0" class="mb-5 mt-5 border">
          <v-card-title class="text-center">Choose Products to Exclude</v-card-title>
          <v-card-text>
            <v-data-table
              id="products-table"
              density="comfortable"
              :loading="is_loading"
              :headers="picker.header"
              :items="SearchProducts()">
              <template v-slot:item="{item,index}">
                <tr>
                  <td>
                    <label>
                      <input :checked="IsAlreadyAdded(item.id)" @change="ToggleSelection($event,item.id)"
                             type="checkbox">{{ item.id }}
                    </label>
                  </td>
                  <td>{{ item.name }}</td>
                  <td>{{ FindBrand(item.manufacturer_id) }}</td>
                </tr>
              </template>
            </v-data-table>
          </v-card-text>
        </v-card>

        <v-card elevation="0" class="mb-5 border">
          <v-card-title class="text-center">Exclusions list</v-card-title>
          <v-card-text>
            <v-data-table
              id="exclusions-table"
              :loading="is_loading"
              :headers="[{title:'Product'},{title:'Action'}]"
              :items="settings.best_sellers">
              <template v-slot:item="{item,index}">
                <tr>
                  <td>{{ FindProduct(item).name }}</td>
                  <td>
                    <v-btn @click="RemoveItem(item)" color="red" size="x-small">Remove</v-btn>
                  </td>
                </tr>
              </template>
            </v-data-table>
          </v-card-text>
        </v-card>
      </v-card-text>
      <v-card-actions>
        <v-spacer></v-spacer>
        <v-btn color="secondary" @click="picker.modal=false">Cancel</v-btn>
        <v-btn color="primary" @click="picker.modal=false">Done</v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import {mapState} from "vuex";
import StrTextField from "@/components/StrTextField.vue";

export default {
  data: () => ({
    picker: {
      header: [{title: 'ID', sortable: true}, {title: 'Product', sortable: true}, {title: 'Brand', sortable: true}],
      modal: false,
      search: "",
      brand: "",
    },
    is_loading: false,
  }),
  components: {StrTextField},
  computed: {
    ...mapState(['settings', 'products', 'manufacturers']),
  },
  methods: {
    SearchProducts() {
      if (this.picker.search.length < 1) {
        // When no search term, still filter by allowed manufacturers
        return this.products.filter(product =>
          this.settings.manufacturers_allowed.includes(product.manufacturer_id)
        );
      }

      // When searching, filter by both search term AND allowed manufacturers
      return this.products.filter(product => {
        return product.name.toLowerCase().includes(this.picker.search.toLowerCase()) &&
          this.settings.manufacturers_allowed.includes(product.manufacturer_id)
      });
    },
    FindProduct(id) {
      return this.products.find(product => product.id == id);
    },
    RemoveItem(id) {
      const index = this.settings.best_sellers.indexOf(+id);
      if (index != -1) {
        this.settings.best_sellers.splice(index, 1);
      }
    },
    IsAlreadyAdded(id) {
      const index = this.settings.best_sellers.indexOf(+id);
      return index != -1;
    },
    FindBrand(id) {
      if (this.manufacturers.length < 1) return '';
      return this.manufacturers.find(brand => brand.id == id).name;
    },
    ToggleSelection(event, prod_id) {
      if (event.target.checked) {
        this.settings.best_sellers.push(+prod_id);
      } else {
        const index = this.settings.best_sellers.indexOf(+prod_id);
        if (index != -1) {
          this.settings.best_sellers.splice(index, 1);
        }
      }
    },
  }
}
</script>
<style scoped>
.scrollable-text {
  max-height: 600px;
  overflow-y: auto;
}
</style>
