<template>
    <div v-if="chat_config">
        <RowTitle top="20px" bottom="20px" size="small">
            An AI-powered assistant that helps customers browse, navigate the catalog, check availability, compare options, and quickly get answers to service-related questions.
            <p>Compatible with <a href="https://api.anthropic.com/v1/organizations/api_keys/{api_key_id}">Anthropic</a>, <a href="https://docs.mistral.ai/getting-started/quickstart/">Mistral</a>, <a href="https://console.groq.com/keys">Groq</a>,
                <a href="https://docs.perplexity.ai/guides/getting-started">Perplexity AI</a>,
                <a href="https://platform.openai.com/api-keys">OpenAI</a>.</p>
        </RowTitle>
        <v-tabs v-model="activeTab" background-color="primary">
            <v-spacer/>
            <v-tab><v-icon class="mr-1">mdi-robot-confused-outline</v-icon> API Key</v-tab>
            <v-tab :disabled="!connected"><v-icon class="mr-1">mdi-palette-outline</v-icon> UI Settings</v-tab>
            <v-spacer/>
        </v-tabs>
        <v-tab-item v-if="activeTab==0">
            <v-card elevation="0">
                <v-card-text v-if="connected">
                    <v-radio-group v-model="chat_config.enabled">
                        <div class="d-flex ma-auto mt-5" style="width:360px">
                            <v-radio label="Enable AI Assistant" :value="true" class="mb-2"/>
                            <v-radio label="Disabled" :value="false" class="mb-2"/>
                        </div>
                    </v-radio-group>
                </v-card-text>

                <v-card-text class="position-relative">
                    <StrTextField label="API Base URL" v-model="chat_config.baseurl" placeholder="For example https://api.groq.com"/>
                </v-card-text>
                <v-card-text class="position-relative">
                    <label class="mb-1">API Key
                        <v-icon size="small" class="ml-1" title="Click to hide/show key" @click="show_key=!show_key">
                            {{show_key ? 'mdi-eye-off' : 'mdi-eye'}}
                        </v-icon>
                    </label>
                    <StrTextField :show_button="true" v-model="chat_config.api_key" :type="show_key?'text':'password'" placeholder="Your API key here..."/>
                </v-card-text>

                <v-card-text v-if="!connected">
                    <v-btn :disabled="!chat_config.api_key || !chat_config.baseurl" :loading="is_loading" @click="FetchModels" prepend-icon="mdi-connection" color="primary" class="d-flex ma-auto">Test Connection</v-btn>
                </v-card-text>

                <template v-if="connected">
                    <v-card-text class="position-relative d-none">
                        <StrTextField type="number" label="Temperature (Lower=Focused/Higher=Creative)" v-model="chat_config.temperature"/>
                    </v-card-text>
                    <v-card-text class="position-relative">
                        <label>Choose an AI Model</label>
                        <v-select variant="outlined" density="compact" v-model="chat_config.model" :items="models"/>
                    </v-card-text>
                    <v-card-text class="position-relative pb-0">
                        <label>Your AI's Instructions (AI Behavior) <br>
                            <i style="color:#878787">The default instructions are fine-tuned for this purpose, there's usually no need to modify this.</i>
                        </label>
                        <v-textarea class="mt-1" bg-color="white" rows="6" rounded="0" variant="outlined" v-model="chat_config.instructions" placeholder="AI instructions..."/>
                    </v-card-text>
                    <v-card-text class="position-relative pt-0">
                        <p class="input-title">Services you offer (Optional)</p>
                        <v-textarea bg-color="white" rows="6" rounded="0" variant="outlined" v-model="chat_config.services"/>
                    </v-card-text>
                </template>
            </v-card>
        </v-tab-item>
        <v-tab-item v-if="activeTab==1">
            <v-card-text class="pb-0">
                <StrTextField label="Chatbox Title" v-model="chat_config.title"/>
            </v-card-text>
            <v-card-text class="pb-0">
                <StrTextField label="Initial message" v-model="chat_config.welcome_txt"/>
            </v-card-text>
            <v-card-text class="pb-0">
                <StrTextField label="Initial message (subtitle)" v-model="chat_config.welcome_sub"/>
            </v-card-text>
            <v-card-text class="pb-0">
                <label class="mb-1">Conversation Starters</label>
                <v-textarea bg-color="white" rows="6" rounded="0" variant="outlined" v-model="chat_config.starters" placeholder="One per line..."/>
            </v-card-text>
            <v-card-text class="pb-0">
                <StrTextField label="Chatbox Width (Pixels)" v-model="chat_config.chatbox_width"/>
            </v-card-text>
            <v-card-text class="pb-0">
                <StrTextField label="Icon URL" v-model="chat_config.icon_url"/>
            </v-card-text>
        </v-tab-item>
    </div>
</template>

<script>
import {mapActions, mapState} from "vuex";
import Axios from "axios";
import RowTitle from "@/components/RowTitle.vue";
import AllMixins from "@/mixins/AllMixins.js";
import StrTextField from "@/components/StrTextField.vue";

export default {
    components: {StrTextField, RowTitle},
    mixins:[AllMixins],
    data: () => ({
        activeTab: 0,
        show_key: false,
        models: [],
        connected: false,
    }),
    computed: {
        ...mapState(['chat_config','is_loading']),
    },
    mounted() {
        this.SetState('chat_config',window.product_catalog.ai_chat_config);
        this.FetchModels();
    },
    methods: {
        ...mapActions(['SetError']),
        FetchModels() {
            if (this.chat_config.api_key) {
                this.SetState('is_loading',true);
                Axios.defaults.headers.common['Authorization'] = 'Bearer '+this.chat_config.api_key;

                // Fetch list of brands
                Axios.get(this.chat_config.baseurl+'/openai/v1/models').then(res => {
                    console.log("FetchModels: ", res.data)
                    this.connected = true;
                    res.data.data.forEach(model => {
                        this.models.push(model.id);
                    });
                }).catch((error) => {
                    this.SetError(error);
                }).finally(() => {
                    this.SetState('is_loading',false);
                });
            }
        }
    }
}
</script>
