import {mapActions,mapState} from "vuex";
import moment from "moment";
import AllMixins from "@/mixins/AllMixins.js";
export default {
    mixins: [AllMixins],
    computed: {
        ...mapState(['google_config','analytics']),
        HasAccessToken() {
            return this.google_config.analytics.access_token;
        },
        PropertySelected() {
            return this.google_config.analytics.ga_property != null;
        },
        Property() {
            return this.google_config.analytics.ga_property;
        }
    },
    methods: {
        ...mapActions(['SetSuccess','SetError','SetAnyState']),
        FetchAnalyticsProperties() {
            let endpoint = '/wp-json/1-800-products/v1/google/ga-properties';
            this.SetGaSettingState('is_loading',true);
            this.$axios.post(endpoint).then(res => {
                console.log(res.data);
                this.SetGaSettingState('properties',res.data);
            }).catch((error) => {
                this.SetError(error.toString());
            }).finally(() => {
                this.SetGaSettingState('is_loading',false);
            });
        },
        SetPropertyAndSave() {
            const google_config = {...this.google_config}
            google_config.analytics.ga_property = this.analytics.property_model;
            this.SaveSettings().then(res => {
                console.log(res);
                location.reload();
            });
        },
        DisconnectGoogle() {
            if (confirm('Disconnect this Property?')) {
                const google_config = {...this.google_config}
                google_config.analytics.ga_property = null;
                this.SaveSettings().then(res => {
                    console.log(res);
                    location.reload();
                });
            }
        },
        FetchRealtimeUsers() {
            let endpoint = '/wp-json/1-800-products/v1/google/ga-realtime-users';
            this.SetGaSettingState('is_loading',true);
            this.$axios.post(endpoint).then(res => {
                if (res.data.error !== undefined) {
                    console.log("FetchRealtimeUsers: ", res.data);
                    return this.SetError(res.data.error.message);
                }
                const realtime_users = [];
                if (!res.data.rows || !res.data.rows.length) {
                    return realtime_users;
                }
                for (const row of res.data.rows) {
                    const [page, country, minutesAgo, deviceCategory] = row.dimensionValues.map(d => d.value);
                    realtime_users.push({
                        page,
                        country,
                        minutesAgo,
                        device: deviceCategory
                    });
                }
                this.SetGaSettingState('realtime_users',realtime_users);
            }).catch((error) => {
                this.SetError(error.toString());
            }).finally(() => {
                this.SetGaSettingState('is_loading',false);
            });
        },
        SetGaSettingState(name,value) {
            const analyticsCopy = {...this.analytics};
            analyticsCopy[name] = value;
            this.SetAnyState({
                target: 'analytics',
                value: analyticsCopy,
            });
        },
        HumanReadableDate(the_date) {
            if (!the_date) {
                return "---"
            }
            return moment(the_date).format('YYYY/MM/DD');
        },
        FetchHistoryReport() {
            let endpoint = '/wp-json/1-800-products/v1/google/ga-history-report';
            this.SetGaSettingState('is_loading',true);
            const form = new FormData;
            form.append('from_date', this.analytics.from_date);
            form.append('end_date', this.analytics.end_date);
            this.$axios.post(endpoint,form).then(res => {
                if (res.data.error !== undefined) {
                    console.log("FetchHistoryReport: ", res.data);
                    return this.SetError(res.data.error.message);
                }
                const history = res.data.sort((a, b) => new Date(a.date) - new Date(b.date));
                this.SetGaSettingState('history_report', history);
            }).catch((error) => {
                this.SetError(error.toString());
            }).finally(() => {
                this.SetGaSettingState('is_loading',false);
            });
        },
        ValidateDateRange() {
            const {from_date,end_date} = this.analytics;
            if (moment(from_date, "YYYY/MM/DD").isAfter(moment(end_date, "YYYY/MM/DD"))) {
                this.SetError("'START' date cannot be later than 'END' date");
                this.SetGaSettingState('from_date', null);
                this.SetGaSettingState('end_date', null);
            }
        }
    },
    watch: {
        "analytics.from_date"() {
            this.SetGaSettingState('show_datepicker',null);
            this.ValidateDateRange();
        },
        "analytics.end_date"() {
            this.SetGaSettingState('show_datepicker',null);
            this.ValidateDateRange();
        }
    }
};
