<template>
    <AppLayout>
        <template #content>
            <Wizard v-if="settings.setup_wizard"/>
            <Default v-else/>
            <Alerts/>
        </template>
    </AppLayout>
</template>

<script>
import axios from "axios";
import Wizard from "./views/Wizard.vue";
import {mapActions, mapState} from "vuex";
import Default from "@/views/Default.vue";
import Alerts from "@/components/Alerts.vue";
import AllMixins from "@/mixins/AllMixins.js";
import AppLayout from "@/layouts/AppLayout.vue";

export default {
    mixins: [AllMixins],
    components: {
        Default,
        Alerts,
        AppLayout,
        Wizard
    },
    data: () => ({
        active_page: 1,
    }),
    created() {
        axios.defaults.headers.common['X-WP-Nonce'] = window.product_catalog.nonce;
        this.SetState('settings',window.product_catalog.catalog_config);
        this.SetState('chat_config',window.product_catalog.ai_chat_config);
        this.SetState('google_config',window.product_catalog.google_config);
    },
    methods: {
        ...mapActions([
            'SetAnyState',
            'SetSuccess',
            'SetError',
        ]),
    },
    computed: {
        ...mapState(['settings','snackbar']),
    },
}
</script>
