// store.js
import {createStore} from 'vuex';
import createPersistedState from 'vuex-persistedstate';

export default createStore({
    state: {
        // Layout
        is_fetching: false,
        is_loading: false,
        is_syncing: false,

        snackbar: {
            visible: false,
            content: '',
            icon: '',
            type: 'success',
        },
        dialog: {
            visible: false,
            title: '',
            content: '',
        },

        // Mobile viewport detection
        is_mobile: false,

        // Settings
        settings: null,

        // Products & Brands
        products: [],
        manufacturers: [],

        // AI Chat
        chat_config: null,

        // Google Config
        google_config: null,

        // Analytics related
        analytics: {
            active_tab: 1,
            is_loading: false,
            property_model: null,
            show_datepicker: null,
            from_date: null,
            end_date:  null,
            all_properties: [],
            realtime_users: [],
            history_report: [],
        },
    },

    // Actions will call mutation
    actions: {
        /** Shared Actions */
        SetSnackbar({commit}, params) {
            commit('SET_ANY_STATE', {
                target: 'snackbar',
                value: params
            });
        },
        SetDialog({commit}, params) {
            commit('SET_ANY_STATE', {
                target: 'dialog',
                value: params
            });
        },
        SetError({commit}, message) {
            commit('SET_ANY_STATE', {
                target: 'snackbar',
                value: {
                    visible: true,
                    content: message,
                    type: 'error',
                    icon: 'mdi-alert-circle-outline'
                }
            });
        },
        SetSuccess({commit}, message) {
            commit('SET_ANY_STATE', {
                target: 'snackbar',
                value: {
                    visible: true,
                    content: message,
                    type: 'success',
                    icon: 'mdi-check-all'
                }
            })
        },
        SetAnyState({commit}, params) {
            commit('SET_ANY_STATE', params)
        }
    },

    // Mutations saves it to State
    mutations: {
        SET_ANY_STATE(state, {target, value}) {
            state[target] = value;
        },
    },

    // Persistent state
    plugins: [createPersistedState({
        paths: []
    })]
});
