<template>
    <div :style="`margin-top:${top??0};margin-bottom:${bottom??0};font-size:${size=='small'? '14px':'25px'}`"
         class="input-title text-center font-weight-light">
        <template v-if="strong">
            <strong>
                <slot></slot>
            </strong>
        </template>
        <template v-else>
            <slot></slot>
        </template>
    </div>
</template>

<script>
export default {
    props: ['size', 'top', 'bottom', 'strong']
}
</script>
