<template>
    <div class="position-relative">
        <StrTextField
            @input="EmitValue"
            @onClick="colorpicker=!colorpicker"
            :model-value="modelValue">
        </StrTextField>
        <div class="current-color" @click="colorpicker=!colorpicker" :style="`background:${modelValue}`"></div>

        <v-card v-if="colorpicker">
            <v-color-picker
                hide-sliders
                hide-canvas
                hide-inputs
                show-swatches
                width="100%"
                elevation="0"
                @update:model-value="EmitValue">
            </v-color-picker>
            <v-card-actions>
                <v-spacer/>
                <v-btn variant="tonal" size="x-small" @click="colorpicker=false">Close</v-btn>
                <v-spacer/>
            </v-card-actions>
        </v-card>
    </div>
</template>
<script>
import {mapState} from "vuex";
import StrTextField from "@/components/StrTextField.vue";
export default {
    props: ['modelValue'],
    data: () => ({
        colorpicker: false,
    }),
    components: {StrTextField},
    computed: {
        ...mapState(['settings']),
    },
    methods: {
        EmitValue(value) {
            this.$emit('update:modelValue', value);
        },
    }
}
</script>
<style>
.v-color-picker-swatches {
    min-height: 300px !important;
}
.current-color {
    height: 30px;
    width: 30px;
    margin: 6px;
    border: 1px solid #d1d1d1;
    border-radius: 50px;
    position: absolute;
    right: 0;
    top: 0;
}
</style>
