import {mapActions,mapState} from "vuex";

export default {
    computed: {
        ...mapState([
            'settings',
            'chat_config',
            'is_fetching',
            'google_config'
        ]),
    },
    methods: {
        ...mapActions(['SetSuccess','SetError','SetAnyState']),
        SetState(target,value) {
            this.SetAnyState({target:target,value:value});
        },
        FetchProducts() {
            return new Promise((resolve, reject) => {
                this.SetState('is_fetching',true);
                const form = new FormData();
                form.append('catalog_api_key', this.settings.catalog_api_key);
                this.$axios.post('/wp-json/1-800-products/v1/products-data',form).then(res => {
                    console.log("FetchProducts: ", res.data.result)
                    if (res.data.result) {
                        this.SetState('products',res.data.products);
                        this.SetState('manufacturers',res.data.manufacturers);
                        resolve(res.data);
                    } else {
                        this.SetError('Failed to fetch products. Please check your API key and try again.');
                    }
                }).catch(() => {
                    this.SetError('Failed to fetch products. Please check your API key and try again.');
                }).finally(() => {
                    this.SetState('is_fetching',false);
                });
            });
        },
        SaveSettings(reload_on_save = false, show_alerts = false, set_wizard = null) {
            return new Promise((resolve, reject) => {
                const form = new FormData();
                const path = '/wp-json/1-800-products/v1/save-settings';
                const newSettings = { ...this.settings };
                this.SetState('is_loading', true);

                if (set_wizard != null) {
                    newSettings.setup_wizard = set_wizard;
                }

                form.append('settings', JSON.stringify(newSettings));
                form.append('chat_config', JSON.stringify(this.chat_config));
                form.append('google_config', JSON.stringify(this.google_config));

                this.$axios.post(path,form).then(res => {
                    console.log("Settings has been saved...", res.data);
                    if (res.data.result) {
                        if (show_alerts) {
                            this.SetSuccess('Settings saved successfully.');
                        }
                        if (reload_on_save) {
                            return location.reload();
                        }
                        resolve(res.data);
                    } else {
                        this.SetError('Failed to save settings. Please try again.');
                        reject(new Error('Save failed'));
                    }
                }).catch(() => {
                    this.SetError('Failed to save settings. Please try again.');
                    reject(new Error('Save failed'));
                }).finally(() => {
                    this.SetState('is_loading', false);
                });
            });
        },
        RerunWizard() {
            if (confirm("Rerun the Setup Wizard?")) {
                this.SaveSettings(true,false,true);
            }
        },
        SyncPages(reload = false) {
            this.SetState('is_syncing',true);
            this.$axios.post("/wp-json/1-800-products/v1/automations/sync-pages").then(res => {
                console.log("SyncPages: ", res.data);
                this.SetSuccess('Product pages have been created! Reloading page in 3 seconds...');
                setTimeout(() => {
                    if (reload) {
                        location.reload();
                    }
                },3000)
            }).catch((error) => {
                console.log(error);
                this.SetError('Failed to create the pages. Please contact developer.');
            }).finally(() => {
                this.SetState('is_syncing',false);
            });
        },
        RetractPages() {
            if (confirm('Are you sure you want to retract the pages?\nWARNING: Do not perform this action if you have Woocommerce.')) {
                const is_confirmed = prompt('Type "delete" to confirm');
                if (is_confirmed == 'delete') {
                    this.SetState('is_syncing',true);
                    this.$axios.post("/wp-json/1-800-products/v1/automations/retract-pages").then(res => {
                        location.reload();
                        this.SetState('is_syncing',false);
                    }).catch((error) => {
                        console.log(error);
                    }).finally(() => {
                        this.SetState('is_syncing',false);
                    });
                } else {
                    this.SetError('Operation canceled.')
                }
            }
        },
    }
};
