<template>
    <p style="margin:0">{{label}}</p>
    <input
        @input="EmitValue"
        :value="modelValue"
        :readonly="readonly"
        class="str-text-field"
        :type="type?type:'text'"
        @click="$emit('onClick')"
        :placeholder="placeholder"
    />
</template>

<script>
import {mapState} from "vuex";

export default {
    props: ['label','type','modelValue','readonly','placeholder'],
    computed: {
        ...mapState(['settings'])
    },
    methods: {
        EmitValue(event) {
            let value = event.target.value;
            if (this.type === 'number') {
                value = parseFloat(value);
            }
            this.$emit('update:modelValue', value);
            this.$emit('input', value);
        },
    },
}
</script>
<style>
input.str-text-field {
    width: 100%;
    padding: 5px 10px;
    margin: 0;
}
</style>
